questionvariables.text:
/*Defining randomised coefficients*/
aa: rand_with_prohib(-5,5,[0]);
bb: rand_with_prohib(-5,5,[0]);
cc: rand_with_prohib(-5,5,[0]);
dd: rand_with_prohib(-5,5,[0]);
ee: rand_with_prohib(-5,5,[0]);
ff: rand_with_prohib(-8,8,[0]);
nn: rand(6)+1
mm: rand(5)+1;
/*Defining the function f(x,y) in terms of its coefficients*/
assume(aa*z^4+bb*x^2>0);
fxy: (%e^(-x))*sqrt(aa*z^nn+bb*x^mm)-((cc*x+dd*z)/(ee*z+ff*x));

/*Model answers*/
ta1: (diff(%e^(-x),x))*(sqrt(aa*z^nn+bb*x^mm))+(diff(sqrt(aa*z^nn+bb*x^mm),x))*((%e^(-x)))-[(expand((diff(cc*x+dd*z,x))*((ee*z+ff*x))-(diff(ee*z+ff*x,x))*((cc*x+dd*z))))/((ee*z+ff*x)^2)],simp;
ta2: (diff(%e^(-x),z))*(sqrt(aa*z^nn+bb*x^mm))+(diff(sqrt(aa*z^nn+bb*x^mm),z))*((%e^(-x)))-[(expand((diff(cc*x+dd*z,z))*((ee*z+ff*x))-(diff(ee*z+ff*x,z))*((cc*x+dd*z))))/((ee*z+ff*x)^2)],simp;
